/**
 * Checks for argument and flag values, declared with `kind` on a spec.
 * Agents make up ids and paths more often than they mistype them, so the
 * checks reject shapes no real value has: control characters, path
 * segments and URL syntax inside ids, and relative output paths that leave
 * the current folder.
 */
import { isAbsolute, relative, resolve } from "node:path";
import { DEPLOYMENT_SLUG_PATTERN } from "../slug.js";
// ASCII control characters: C0 and DEL.
const CONTROL_CHARACTER = /[\u0000-\u001f\u007f]/;
// Characters that turn an id into a path, a query, or an encoded value.
const ID_FORBIDDEN = /[/\\%?#\s]|\.\./;
/** Why `value` is not a valid `kind`, or undefined when it is. */
export function checkValueKind(kind, value, cwd = process.cwd()) {
    if (CONTROL_CHARACTER.test(value)) {
        return "must not contain control characters";
    }
    switch (kind) {
        case "slug":
            return ID_FORBIDDEN.test(value) ? idProblem(value) : slugProblem(value);
        case "sessionId":
        case "releaseId":
            return value === "" ? "must not be empty" : idProblem(value);
        case "teamId":
            return /^[1-9][0-9]*$/.test(value) ? undefined : "must be a positive team id";
        case "url":
            return urlProblem(value);
        case "path":
            return value === "" ? "must not be empty" : undefined;
        case "outputPath":
            return outputPathProblem(value, cwd);
    }
    const unexpected = kind;
    throw new Error(`unexpected value kind ${String(unexpected)}`);
}
function idProblem(value) {
    return ID_FORBIDDEN.test(value)
        ? `must be a plain id: no "/", "\\", "..", "%", "?", "#", or spaces (got ${JSON.stringify(value)})`
        : undefined;
}
function slugProblem(value) {
    return DEPLOYMENT_SLUG_PATTERN.test(value)
        ? undefined
        : `must use lowercase letters, digits, '-' or '_' (max 64 chars; got ${JSON.stringify(value)})`;
}
function urlProblem(value) {
    let url;
    try {
        url = new URL(value);
    }
    catch {
        return `must be an http or https URL (got ${JSON.stringify(value)})`;
    }
    return url.protocol === "http:" || url.protocol === "https:"
        ? undefined
        : `must be an http or https URL (got ${JSON.stringify(value)})`;
}
function outputPathProblem(value, cwd) {
    if (value === "") {
        return "must not be empty";
    }
    if (isAbsolute(value)) {
        return undefined;
    }
    const inside = relative(cwd, resolve(cwd, value));
    return inside === ".." || inside.startsWith("../") || inside.startsWith("..\\")
        ? `must stay inside the current folder, or be an absolute path (got ${JSON.stringify(value)})`
        : undefined;
}
